/* ---------- 客人自己改時間：療程開始 24 小時前、每筆最多自己改 2 次 ---------- */
const OWNER_PHONE_ = '0963183093';
function bookingFind_(code, phone) {
  code = String(code || '').trim().toUpperCase();
  const pd = String(phone || '').replace(/\D/g, '');
  if (!/^PS\d{6}-\d{4}-[A-Z0-9]{3}$/.test(code) || pd.length < 8) return null;
  const now = new Date();
  return calendar_().getEvents(new Date(now.getTime() - 2 * 864e5), new Date(now.getTime() + (CONFIG.DAYS_AHEAD + 1) * 864e5)).filter(function (e) {
    const d = e.getDescription() || '', m = d.match(/電話：([^\n]*)/);
    return (e.getTitle() || '').indexOf(CONFIG.TAG) === 0 && d.indexOf('預約編號：' + code) >= 0 && !!m && m[1].replace(/\D/g, '') === pd;
  })[0] || null;
}
function bookingInfo_(e) {
  const d = e.getDescription() || '', t = e.getTitle() || '';
  const name = ((d.match(/療程：([^（\n]*)/) || [])[1] || '').trim();
  const sv = SERVICES.filter(function (s) { return s.name === name; })[0];
  const n = Number((d.match(/自己改期：(\d+)/) || [])[1] || 0);
  const st = e.getStartTime(), hrs = (st.getTime() - Date.now()) / 36e5, done = /已取消|已結帳/.test(t);
  const reason = done ? '這筆預約已經取消或完成了。' : hrs < 24 ? '離療程開始不到 24 小時，請直接 LINE 島主幫您調整。' : n >= 2 ? '這筆預約已經自己改過 2 次，請直接 LINE 島主幫您調整。' : !sv ? '這個療程請直接 LINE 島主幫您改時間。' : '';
  return {service: name, svcKey: sv ? sv.key : '', min: sv ? sv.min : 0,
    date: Utilities.formatDate(st, CONFIG.TZ, 'yyyy-MM-dd'), start: Utilities.formatDate(st, CONFIG.TZ, 'HH:mm'), end: Utilities.formatDate(e.getEndTime(), CONFIG.TZ, 'HH:mm'),
    changes: n, canChange: !reason, reason: reason};
}
function bookingGet(p) {
  p = p || {};
  const e = bookingFind_(p.code, p.phone);
  if (!e) return {ok: false, error: '找不到這筆預約，請確認預約編號和手機。'};
  const i = bookingInfo_(e); i.ok = true; i.code = String(p.code).trim().toUpperCase();
  return i;
}
function bookingMove(p) {
  p = p || {};
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const code = String(p.code || '').trim().toUpperCase(), e = bookingFind_(code, p.phone);
    if (!e) return {ok: false, error: '找不到這筆預約，請確認預約編號和手機。'};
    const i = bookingInfo_(e);
    if (!i.canChange) return {ok: false, error: i.reason};
    if (!isBookableDate_(p.date) || !/^\d{2}:\d{2}$/.test(p.start || '')) return {ok: false, error: '日期或時間不正確，請重新選擇。'};
    if (p.date === i.date && p.start === i.start) return {ok: false, error: '這就是原本的時間喔，請選另一個時段。'};
    const slot = slotsFor_(p.date).filter(function (x) { return x.start === p.start; })[0];
    if (!slot || slot.fit < i.min) return {ok: false, error: '這個時段剛剛被預約走了，請換一個時間。'};
    const s = toMin_(p.start), old = i.date + ' ' + i.start, nw = p.date + ' ' + p.start + '–' + toTime_(s + i.min);
    e.setTime(toDate_(p.date, s), toDate_(p.date, s + i.min));
    let d = e.getDescription() || '';
    d = /自己改期：\d+/.test(d) ? d.replace(/自己改期：\d+/, '自己改期：' + (i.changes + 1)) : d + '\n自己改期：1';
    d += '\n改期紀錄：' + Utilities.formatDate(new Date(), CONFIG.TZ, 'MM-dd HH:mm') + ' 客人自己從 ' + old + ' 改到 ' + nw;
    e.setDescription(d);
    const name = ((d.match(/客人：([^\n]*)/) || [])[1] || '').trim(), ph = ((d.match(/電話：([^\n]*)/) || [])[1] || '').trim();
    let line = false;
    try { line = linePushPhone_(ph, '🌿 時間改好了！\n預約編號：' + code + '\n' + i.service + '\n📅 新時間：' + nw + '\n（原本：' + old + '）\n\n訂金和套票都會跟著新時間走，您不用再做任何事。'); } catch (x) {}
    try { linePushPhone_(OWNER_PHONE_, '🔁 客人自己改了時間\n' + name + '｜' + i.service + '\n' + old + ' → ' + nw + '\n預約編號：' + code); } catch (x) {}
    return {ok: true, service: i.service, date: p.date, start: p.start, end: toTime_(s + i.min), line: !!line};
  } finally { lock.releaseLock(); }
}

